17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	import java.util.regex.Pattern;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    /**
59	     * Syntactic email validation: a non-empty local part, a single '@', and a
60	     * domain with at least one dot-separated label ending in a letter-only TLD.
61	     */
62	    private static final Pattern EMAIL_PATTERN =
63	        Pattern.compile("^[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+(\\.[A-Za-z0-9-]+)*\\.[A-Za-z]{2,}$");
64	
65	    private final ClinicService clinicService;
66	
67	    private final OwnerMapper ownerMapper;
68	
69	    private final PetMapper petMapper;
70	
71	    private final VisitMapper visitMapper;
72	
73	    public OwnerRestControllerV1(ClinicService clinicService,
74	                                 OwnerMapper ownerMapper,
75	                                 PetMapper petMapper,
76	                                 VisitMapper visitMapper) {
77	        this.clinicService = clinicService;
78	        this.ownerMapper = ownerMapper;
79	        this.petMapper = petMapper;
80	        this.visitMapper = visitMapper;
81	    }
82	
83	    /**
84	     * Normalise a raw telephone number to E.164 form.
85	     *
86	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
87	     * code are kept when present; otherwise country code '+61' is assumed and a
88	     * single leading '0' is dropped from the national digits. The result must have
89	     * between 8 and 15 digits after the '+'.
90	     *
91	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
92	     */
93	    static String toE164(String raw) {
94	        if (raw == null) {
95	            return null;
96	        }
97	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
98	        String digits;
99	        if (cleaned.startsWith("+")) {
100	            digits = cleaned.substring(1);
101	        } else {
102	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
103	            digits = "61" + national;
104	        }
105	        if (!digits.matches("[0-9]{8,15}")) {
106	            return null;
107	        }
108	        return "+" + digits;
109	    }
110	
111	    /**
112	     * Build the customer code for a new owner as {@code '<LAST3>-<NNNN>'}, where LAST3 is the
113	     * upper-cased first three letters of the last name and NNNN is a global 4-digit zero-padded
114	     * sequence equal to one more than the current number of owners.
115	     */
116	    private String nextCustomerCode(String lastName) {
117	        String letters = lastName == null ? "" : lastName;
118	        String last3 = letters.substring(0, Math.min(3, letters.length())).toUpperCase();
119	        int sequence = this.clinicService.findAllOwners().size() + 1;
120	        return String.format("%s-%04d", last3, sequence);
121	    }
122	
123	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
124	    @Override
125	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
126	        Collection<Owner> owners;
127	        if (lastName != null) {
128	            owners = this.clinicService.findOwnerByLastName(lastName);
129	        } else {
130	            owners = this.clinicService.findAllOwners();
131	        }
132	        if (owners.isEmpty()) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
136	    }
137	
138	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
139	    @Override
140	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
141	        Owner owner = this.clinicService.findOwnerById(ownerId);
142	        if (owner == null) {
143	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
144	        }
145	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
151	        String telephone = toE164(ownerFieldsDto.getTelephone());
152	        if (telephone == null) {
153	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
154	        }
155	        String email = ownerFieldsDto.getEmail();
156	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
157	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
158	        }
159	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
160	            .map(Owner::getTelephone)
161	            .map(OwnerRestControllerV1::toE164)
162	            .filter(existing -> existing != null)
163	            .anyMatch(telephone::equals);
164	        if (telephoneInUse) {
165	            return new ResponseEntity<>(HttpStatus.CONFLICT);
166	        }
167	        HttpHeaders headers = new HttpHeaders();
168	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
169	        owner.setTelephone(telephone);
170	        owner.setEmail(email == null ? null : email.toLowerCase());
171	        if (owner.getRegistrationDate() == null) {
172	            owner.setRegistrationDate(LocalDate.now());
173	        }
174	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
175	        this.clinicService.saveOwner(owner);
176	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
177	        headers.setLocation(UriComponentsBuilder.newInstance()
178	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
179	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
180	    }
181	
182	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
183	    @Override
184	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
185	        String telephone = toE164(ownerFieldsDto.getTelephone());
186	        if (telephone == null) {
187	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
188	        }
189	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
190	        if (currentOwner == null) {
191	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
192	        }
193	        String email = ownerFieldsDto.getEmail();
194	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
195	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
196	        }
197	        currentOwner.setAddress(ownerFieldsDto.getAddress());
198	        currentOwner.setCity(ownerFieldsDto.getCity());
199	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
200	        currentOwner.setLastName(ownerFieldsDto.getLastName());
201	        currentOwner.setTelephone(telephone);
202	        currentOwner.setEmail(email == null ? null : email.toLowerCase());
203	        this.clinicService.saveOwner(currentOwner);
204	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
205	    }
206	
207	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
208	    @Transactional
209	    @Override
210	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
211	        Owner owner = this.clinicService.findOwnerById(ownerId);
212	        if (owner == null) {
213	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
214	        }
215	        this.clinicService.deleteOwner(owner);
216	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
217	    }
218	
219	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
220	    @Override
221	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
222	        Owner owner = this.clinicService.findOwnerById(ownerId);
223	        if (owner == null) {
224	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
225	        }
226	        HttpHeaders headers = new HttpHeaders();
227	        Pet pet = petMapper.toPet(petFieldsDto);
228	        owner.setId(ownerId);
229	        pet.setOwner(owner);
230	        pet.getType().setName(null);
231	        this.clinicService.savePet(pet);
232	        PetDto petDto = petMapper.toPetDto(pet);
233	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
234	            .buildAndExpand(pet.getId()).toUri());
235	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
236	    }
237	
238	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
239	    @Override
240	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
241	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
242	        if (currentOwner != null) {
243	            Pet currentPet = this.clinicService.findPetById(petId);
244	            if (currentPet != null) {
245	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
246	                currentPet.setName(petFieldsDto.getName());
247	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
248	                this.clinicService.savePet(currentPet);
249	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
250	            }
251	        }
252	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
253	    }
254	
255	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
256	    @Override
257	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
258	        HttpHeaders headers = new HttpHeaders();
259	        Visit visit = visitMapper.toVisit(visitFieldsDto);
260	        Pet pet = new Pet();
261	        pet.setId(petId);
262	        visit.setPet(pet);
263	        this.clinicService.saveVisit(visit);
264	        VisitDto visitDto = visitMapper.toVisitDto(visit);
265	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
266	            .buildAndExpand(visit.getId()).toUri());
267	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
268	    }
269	
270	
271	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
272	    @Override
273	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
274	        Owner owner = this.clinicService.findOwnerById(ownerId);
275	        if (owner != null) {
276	            Pet pet = owner.getPet(petId);
277	            if (pet != null) {
278	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
279	            }
280	        }
281	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
282	    }
283	}
